pub fn squash(v: &mut Vec<String>) {
    if v.is_empty() {
        return;
    }

    let mut write = 0;
    for read in 1..v.len() {
        if v[read] != v[write] {
            write += 1;
            v[write] = v[read].clone();
        }
    }
    v.truncate(write + 1);

    for s in v.iter_mut() {
        *s = s.trim().to_string();
    }
}
