use std::collections::HashMap;

struct Node<K, V> {
    key: K,
    value: V,
    prev: Option<usize>,
    next: Option<usize>,
}

pub struct Lru<K: Eq + std::hash::Hash + Clone, V> {
    cap: usize,
    map: HashMap<K, usize>,
    nodes: Vec<Option<Node<K, V>>>,
    head: Option<usize>,
    tail: Option<usize>,
    free: Vec<usize>,
    len: usize,
}

impl<K: Eq + std::hash::Hash + Clone, V> Lru<K, V> {
    pub fn new(cap: usize) -> Self {
        assert!(cap >= 1);
        Lru {
            cap,
            map: HashMap::with_capacity(cap),
            nodes: Vec::with_capacity(cap),
            head: None,
            tail: None,
            free: Vec::new(),
            len: 0,
        }
    }

    fn remove_node(&mut self, idx: usize) {
        let (prev, next) = match &mut self.nodes[idx] {
            Some(node) => (node.prev.take(), node.next.take()),
            None => return,
        };

        if let Some(p) = prev {
            if let Some(ref mut n) = self.nodes[p] {
                n.next = next;
            }
        } else {
            self.head = next;
        }

        if let Some(n) = next {
            if let Some(ref mut n) = self.nodes[n] {
                n.prev = prev;
            }
        } else {
            self.tail = prev;
        }
    }

    fn insert_at_head(&mut self, idx: usize) {
        if let Some(ref mut node) = self.nodes[idx] {
            node.prev = None;
            node.next = self.head;
        }

        if let Some(h) = self.head {
            if let Some(ref mut n) = self.nodes[h] {
                n.prev = Some(idx);
            }
        }

        self.head = Some(idx);

        if self.tail.is_none() {
            self.tail = Some(idx);
        }
    }

    fn move_to_head(&mut self, idx: usize) {
        self.remove_node(idx);
        self.insert_at_head(idx);
    }

    fn alloc_idx(&mut self) -> usize {
        if let Some(idx) = self.free.pop() {
            idx
        } else {
            let idx = self.nodes.len();
            self.nodes.push(None);
            idx
        }
    }

    pub fn get(&mut self, k: &K) -> Option<&V> {
        let idx = *self.map.get(k)?;
        self.move_to_head(idx);
        self.nodes[idx].as_ref().map(|n| &n.value)
    }

    pub fn put(&mut self, k: K, v: V) {
        if let Some(&idx) = self.map.get(&k) {
            if let Some(ref mut node) = self.nodes[idx] {
                node.value = v;
            }
            self.move_to_head(idx);
            return;
        }

        if self.len >= self.cap {
            if let Some(tail_idx) = self.tail {
                self.remove_node(tail_idx);
                if let Some(node) = self.nodes[tail_idx].take() {
                    self.map.remove(&node.key);
                    self.free.push(tail_idx);
                }
                self.len -= 1;
            }
        }

        let idx = self.alloc_idx();
        self.nodes[idx] = Some(Node {
            key: k.clone(),
            value: v,
            prev: None,
            next: None,
        });
        self.insert_at_head(idx);
        self.map.insert(k, idx);
        self.len += 1;
    }
}
