use std::sync::{Arc, Mutex};
use std::sync::mpsc;
use std::thread;

pub fn parallel_map<T, R, F>(items: Vec<T>, f: F, workers: usize) -> Vec<R>
where
    T: Send + 'static,
    R: Send + 'static,
    F: Fn(T) -> R + Send + Sync + 'static,
{
    let n = items.len();
    let results: Arc<Mutex<Vec<Option<R>>>> =
        Arc::new(Mutex::new(vec![None; n]));
    let f = Arc::new(f);

    let (tx, rx) = mpsc::channel::<(usize, T)>();
    let rx = Arc::new(Mutex::new(rx));

    let mut handles = Vec::with_capacity(workers);
    for _ in 0..workers {
        let rx = Arc::clone(&rx);
        let f = Arc::clone(&f);
        let results = Arc::clone(&results);

        handles.push(thread::spawn(move || {
            loop {
                let task = {
                    let rx = rx.lock().unwrap();
                    rx.recv()
                };
                match task {
                    Ok((i, item)) => {
                        let result = f(item);
                        let mut res = results.lock().unwrap();
                        res[i] = Some(result);
                    }
                    Err(_) => break,
                }
            }
        }));
    }

    for (i, item) in items.into_iter().enumerate() {
        tx.send((i, item)).unwrap();
    }
    drop(tx);

    for h in handles {
        h.join().unwrap();
    }

    Arc::try_unwrap(results)
        .unwrap()
        .into_inner()
        .unwrap()
        .into_iter()
        .map(Option::unwrap)
        .collect()
}
