pub struct PairsMut<'a, T> {
    ptr: *mut T,
    len: usize,
    _marker: std::marker::PhantomData<&'a mut T>,
}

pub fn pairs_mut<'a, T>(s: &mut [T]) -> PairsMut<'a, T> {
    PairsMut {
        ptr: s.as_mut_ptr(),
        len: s.len() / 2 * 2,
        _marker: std::marker::PhantomData,
    }
}

impl<'a, T> Iterator for PairsMut<'a, T> {
    type Item = (&'a mut T, &'a mut T);

    fn next(&mut self) -> Option<Self::Item> {
        if self.len < 2 {
            return None;
        }
        unsafe {
            let p = self.ptr;
            self.ptr = p.add(2);
            self.len -= 2;
            // Soundness:
            // - Each iteration advances ptr by 2, so pairs never overlap.
            // - len is truncated to even on construction; we stop when len < 2.
            // - Therefore each element in the original slice is yielded at most once.
            // - The two references are to disjoint memory regions.
            let a = &mut *p;
            let b = &mut *p.add(1);
            Some((a, b))
        }
    }
}
