use std::future::Future;
use std::pin::Pin;
use std::sync::{Arc, Condvar, Mutex};
use std::task::{Context, Poll, RawWaker, RawWakerVTable, Waker};

struct BlockOnState {
    notified: Mutex<bool>,
    cvar: Condvar,
}

fn clone_waker(data: *const ()) -> RawWaker {
    let state = data as *const Arc<BlockOnState>;
    unsafe { Arc::increment_strong_count(state) };
    RawWaker::new(data, &WAKER_VTABLE)
}

fn wake_by_ref(data: *const ()) {
    let state = unsafe { &*(data as *const Arc<BlockOnState>) };
    let mut notified = state.notified.lock().unwrap();
    *notified = true;
    state.cvar.notify_one();
}

fn wake(data: *const ()) {
    wake_by_ref(data);
}

fn drop_waker(data: *const ()) {
    let state = data as *const Arc<BlockOnState>;
    unsafe { Arc::decrement_strong_count(state) };
}

const WAKER_VTABLE: RawWakerVTable = unsafe {
    RawWakerVTable::new(clone_waker, wake, wake_by_ref, drop_waker)
};

pub fn block_on<F: Future>(fut: F) -> F::Output {
    let state = Arc::new(BlockOnState {
        notified: Mutex::new(false),
        cvar: Condvar::new(),
    });

    let waker = unsafe {
        Waker::from_raw(RawWaker::new(Arc::into_raw(&state) as *const (), &WAKER_VTABLE))
    };

    let mut cx = Context::from_waker(&waker);
    let mut fut = Pin::new(fut);

    loop {
        match fut.as_mut().poll(&mut cx) {
            Poll::Ready(val) => return val,
            Poll::Pending => {
                let mut notified = state.notified.lock().unwrap();
                while !*notified {
                    notified = state.cvar.wait(notified).unwrap();
                }
                *notified = false;
            }
        }
    }
}

pub struct YieldNow {
    pub remaining: u32,
}

impl Future for YieldNow {
    type Output = ();

    fn poll(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<()> {
        if self.remaining > 0 {
            self.remaining -= 1;
            cx.waker().wake_by_ref();
            Poll::Pending
        } else {
            Poll::Ready(())
        }
    }
}
